		public static int CheckContestEntry(global::Dpr.Contest.CategoryID categoryID, global::Dpr.Contest.RankID rankID) {
            if (!CheckRankClearFlag(categoryID, rankID))
                return 0;

            uint memberCount = PlayerWork.playerParty.GetMemberCount();
            int validPokeNum = 0;
            int furRibbonNum = 0;
            for (uint i = 0; i < memberCount; i++)
            {
                PokemonParam pokeParam = PlayerWork.playerParty.GetMemberPointer(i);
                if (CheckPokeStatus(pokeParam) && HasValidContestWaza(pokeParam))
                    validPokeNum++;

                if (categoryID == CategoryID.Fur && CheckEntryFurContest(pokeParam))
                    furRibbonNum++;
            }

            if (categoryID == CategoryID.Fur && furRibbonNum < 1)
                return 2;

            return validPokeNum > 0 ? 3 : 1;
        }
		public static bool CanEntryContest(global::Pml.PokePara.PokemonParam pokeParam, global::Dpr.Contest.CategoryID categoryID) {
            if (!CheckPokeStatus(pokeParam))
                return false;

            if (!HasValidContestWaza(pokeParam))
                return false;

            if (IsMultiMode)
                return true;

            if (categoryID == CategoryID.Fur)
                return CheckEntryFurContest(pokeParam);

            return true;
        }
		public static bool CheckPokeStatus(global::Pml.PokePara.PokemonParam pokeParam) {
            return !pokeParam.IsEgg(EggCheckType.BOTH_EGG) && !pokeParam.IsHpZero();
        }
		private static bool CheckEntryFurContest(global::Pml.PokePara.PokemonParam pokeParam) {
            return pokeParam.HaveRibbon((uint)Pml.RibbonNo.CONTEST_STAR);
        }
		public static bool HasValidContestWaza(global::Pml.PokePara.PokemonParam pokeParam) {
            return FindValidWazaIndex(pokeParam) >= 0;
        }
		public static int FindValidWazaIndex(global::Pml.PokePara.PokemonParam pokeParam) {
            byte wazaCount = pokeParam.GetWazaCount();
            for (byte i = 0; i < wazaCount; i++)
            {
                if (Pml.WazaData.WazaDataSystem.IsValid(pokeParam.GetWazaNo(i)))
                    return i;
            }
            return -1;
        }
		private static bool CheckRankClearFlag(global::Dpr.Contest.CategoryID categoryID, global::Dpr.Contest.RankID rankID) {
            if (categoryID == CategoryID.Tutorial)
                return true;

            if (IsMultiMode)
                return true;

            if (rankID == RankID.Normal)
                return true;

            return IsClearPrevRank(categoryID, rankID);
        }
		private static bool IsClearPrevRank(global::Dpr.Contest.CategoryID categoryID, global::Dpr.Contest.RankID rankID) {
            EvWork.SYSFLAG_INDEX flagIndex;
            if (categoryID == CategoryID.Fur)
                flagIndex = FindSercretContestClearFlagIndex(rankID - 1);
            else
                flagIndex = FindStandardContestClearFlagIndex(categoryID, rankID - 1);

            return EvDataManager.Instanse.GetSysFlag(flagIndex) > 0;
        }
		public static void ApplyContestRecord(global::Dpr.Contest.ContestRewardDataModel resultDataModel) {
            UpdateContestEntryCnt();
            if (resultDataModel.IsBestPerformer)
                UpdateBestPerformerCnt();

            UpdateWinRate();
            if (resultDataModel.resultID == ResultID.Success)
                UpdateContestClearRank();

            UpdateGetRibbonCnt(resultDataModel.categoryRibbon != (uint)Pml.RibbonNo.NULL,
                               resultDataModel.contestStarRibbon != (uint)Pml.RibbonNo.NULL,
                               resultDataModel.twinkleStarRibbon != (uint)Pml.RibbonNo.NULL);
        }
		private static void UpdateContestEntryCnt() {
            int recordIndex = (int)RECORD_ID.RECID_CONTEST_PLAY_SINGLE + (int)playMode;
            uint count = RecordWork.Get(recordIndex);
            if (count >= ContestDataConstants.MAX_REC_ENTRY_CNT)
            {
                ContestUtils.EmitLog(string.Format("[Record] Contest Entry Cnt is Max [{0}]", count));
                return;
            }
            RecordWork.Add(recordIndex, 1);
            ContestUtils.EmitLog(string.Format("[Record] Add Entry Cnt : [{0}] - [{1}]", (RECORD_ID)recordIndex, count));
        }
		private static void UpdateBestPerformerCnt() {
            int recordIndex = (int)RECORD_ID.RECID_CONTEST_WIN_SINGLE + (int)playMode;
            uint count = RecordWork.Get(recordIndex);
            if (count >= ContestDataConstants.MAX_REC_WIN_CNT)
            {
                // Shipped: the best-performer path logs the entry-count message.
                ContestUtils.EmitLog(string.Format("[Record] Contest Entry Cnt is Max [{0}]", count));
                return;
            }
            RecordWork.Add(recordIndex, 1);
            ContestUtils.EmitLog(string.Format("[Record] Add BestPerformer Cnt : [{0}] - [{1}]", (RECORD_ID)recordIndex, count));
        }
		private static void UpdateContestClearRank() {
            if (categoryID == CategoryID.Tutorial || categoryID == CategoryID.Fur)
                return;

            int recordIndex = (int)RECORD_ID.RECID_CONTEST_STYLE_RANK - 1 + (int)categoryID;
            uint prevRank = RecordWork.Get(recordIndex);
            if (prevRank != 0)
            {
                ContestUtils.EmitLog(string.Format("[Record] Prev Record : [{0}] - [{1}]", (RECORD_ID)recordIndex, (RankID)prevRank));
                if ((int)rankID <= prevRank)
                    return;
            }
            RecordWork.Set(recordIndex, (uint)rankID);
            ContestUtils.EmitLog(string.Format("[Record] Set New Record : [{0}] - [{1}]", (RECORD_ID)recordIndex, rankID));
        }
		private static void UpdateWinRate() {
            for (int i = 0; i < (int)ContestMode.NUM; i++)
            {
                uint playCount = RecordWork.Get((int)RECORD_ID.RECID_CONTEST_PLAY_SINGLE + i);
                if (playCount != 0)
                {
                    uint winCount = RecordWork.Get((int)RECORD_ID.RECID_CONTEST_WIN_SINGLE + i);
                    uint winRate = (uint)((float)winCount / (float)playCount * 100f + 0.5f);
                    int rateIndex = (int)RECORD_ID.RECID_CONTEST_RATE_SINGLE + i;
                    RecordWork.Set(rateIndex, winRate);
                    ContestUtils.EmitLog(string.Format("[Record] Set New WinRate  : [{0}] - [{1}]", (RECORD_ID)rateIndex, winRate));
                }
            }
        }
		private static void UpdateGetRibbonCnt(bool hasCategoryRibbon, bool hasContestStarRibbon, bool hasTwinkleStarRibbon) {
            uint addNum = 0;
            if (hasCategoryRibbon)
                addNum++;

            if (hasContestStarRibbon)
                addNum++;

            if (hasTwinkleStarRibbon)
                addNum++;

            if (addNum == 0)
                return;

            uint ribbonNum = RecordWork.Get(RECORD_ID.RECID_CONTEST_GET_RIBBON);
            if (ribbonNum >= ContestDataConstants.MAX_REC_GET_RIBBON_NUM)
            {
                ContestUtils.EmitLog(string.Format("[Record] Get Ribbon Num is Max [{0}]", ContestDataConstants.MAX_REC_GET_RIBBON_NUM));
                return;
            }
            RecordWork.Add(RECORD_ID.RECID_CONTEST_GET_RIBBON, addNum);
            ContestUtils.EmitLog(string.Format("[Record] Add Get Ribbon Num : [{0}] - [{1}] + [{2}]", RECORD_ID.RECID_CONTEST_GET_RIBBON, ribbonNum, addNum));
        }
