		public static void ApplyReportData_MultiMode(global::Dpr.Contest.ResultDataModel resultDataModel) {
            if (resultDataModel.multiResult == 2)
                return;

            uint result = resultDataModel.resultID == ResultID.Success ? 1u : 0u;
            uint category = (uint)resultDataModel.categoryID;
            uint level = (uint)resultDataModel.rankID;
            uint monsNo = (uint)resultDataModel.monsNo;
            uint costume = resultDataModel.playerFashion;
            uint wazaId = (uint)resultDataModel.wazaNo;
            uint score = (uint)resultDataModel.GetPlayerData().GetTotalScore();
            uint bestPerformer = resultDataModel.IsUserWin() ? 1u : 0u;
            if (playMode == ContestMode.Local)
                PlayReportManager.SaveReportLog_ContestP2P(result, category, level, monsNo, costume, wazaId, score, bestPerformer);
            else if (playMode == ContestMode.Internet)
                PlayReportManager.SaveReportLog_ContestNet(result, category, level, monsNo, costume, wazaId, score, bestPerformer);
        }
		public static global::Dpr.EvScript.EvWork.SYSFLAG_INDEX FindStandardContestClearFlagIndex(global::Dpr.Contest.CategoryID categoryID, global::Dpr.Contest.RankID rankID) {
            if (rankID == RankID.Master)
                return EvWork.SYSFLAG_INDEX.SYS_FLAG_CON_STYLE_MASTER + ((int)categoryID - (int)CategoryID.Style);

            return EvWork.SYSFLAG_INDEX.SYS_FLAG_CON_STYLE_NORMAL + ((int)categoryID - (int)CategoryID.Style) * 3 + ((int)rankID - (int)RankID.Normal);
        }
		public static global::Dpr.EvScript.EvWork.SYSFLAG_INDEX FindSercretContestClearFlagIndex(global::Dpr.Contest.RankID rankID) {
            return EvWork.SYSFLAG_INDEX.SYS_FLAG_CON_FUR_NORMAL + ((int)rankID - (int)RankID.Normal);
        }
		public static void ResetContestData() {
            CONTEST_DATA contestData = PlayerWork.playerData.contestdata;
            contestData.photoDatas = new CON_PHOTO_DATA[ContestDataConstants.MAX_CON_PHOTO_DATA_NUM];
            for (int i = 0; i < ContestDataConstants.MAX_CON_PHOTO_DATA_NUM; i++)
            {
                contestData.photoDatas[i].fxDatas = new CON_PHOTO_FX_DATA[ContestDataConstants.MAX_PHOTO_FX_DATA_NUM];
                for (int j = 0; j < ContestDataConstants.MAX_PHOTO_FX_DATA_NUM; j++)
                    contestData.photoDatas[i].fxDatas[j].groupNo = -1;

                contestData.photoDatas[i].hasData = false;
            }
            PlayerWork.playerData.contestdata = contestData;

            CON_PHOTO_LANG_DATA langData = PlayerWork.contestPhotoLangData;
            langData.styleMonsLangID = 0;
            langData.beautifulMonsLangID = 0;
            langData.cuteMonsLangID = 0;
            langData.cleverMonsLangID = 0;
            langData.strongMonsLangID = 0;
            PlayerWork.contestPhotoLangData = langData;

            CON_PHOTO_EXT_DATA[] extDatas = PlayerWork.contestPhotoExtData = new CON_PHOTO_EXT_DATA[ContestDataConstants.MAX_CON_PHOTO_DATA_NUM];
            for (int i = 0; i < extDatas.Length; i++)
                extDatas[i].nickname = string.Empty;

            PlayerWork.contestPhotoExtData = extDatas;
        }
