		private static void SetMonsLanguageID(global::Dpr.Contest.CategoryID categoryID, byte langID) {
            CON_PHOTO_LANG_DATA langData = PlayerWork.contestPhotoLangData;
            switch (categoryID)
            {
                case CategoryID.Style:
                    langData.styleMonsLangID = langID;
                    break;
                case CategoryID.Beautiful:
                    langData.beautifulMonsLangID = langID;
                    break;
                case CategoryID.Cute:
                    langData.cuteMonsLangID = langID;
                    break;
                case CategoryID.Clever:
                    langData.cleverMonsLangID = langID;
                    break;
                case CategoryID.Strong:
                    langData.strongMonsLangID = langID;
                    break;
                default:
                    ContestUtils.EmitLog(string.Format("{0} : Can not Capture!!", categoryID));
                    return;
            }
            PlayerWork.contestPhotoLangData = langData;
        }
		private static void SetPhotoMonsName(global::Dpr.Contest.CategoryID categoryID, string nickname) {
            int index = (int)categoryID - 1;
            CON_PHOTO_EXT_DATA extData = PlayerWork.contestPhotoExtData[index];
            if (index < ContestDataConstants.MAX_CON_PHOTO_DATA_NUM)
            {
                extData.nickname = nickname;
                PlayerWork.contestPhotoExtData[index] = extData;
            }
            else
            {
                ContestUtils.EmitLog(string.Format("{0} : Can not Capture!!", categoryID));
            }
        }
